import{_ as e,V as o,W as c,a1 as l,Y as n,Z as s,$ as t,X as p,F as i}from"./framework-7b46bad1.js";const u={},k=p(`<p>纯 Java 构建 AI 对话机器人：AgentScope 2.0 Builder 模式与流式输出实战</p><figure><img src="https://imgbed.ppai.top/file/1784789086832_cover.jpg" alt="cover.jpg" tabindex="0" loading="lazy"><figcaption>cover.jpg</figcaption></figure><blockquote><p>同样的 Builder 链，能搭出&quot;一问一答&quot;的哑巴，也能搭出&quot;边说边想&quot;的智者——区别只在于你开了哪几个开关</p></blockquote><h1 id="你的第一个-java-agent-builder-模式、流式输出与思考模式完全指南" tabindex="-1"><a class="header-anchor" href="#你的第一个-java-agent-builder-模式、流式输出与思考模式完全指南" aria-hidden="true">#</a> 你的第一个 Java Agent：Builder 模式、流式输出与思考模式完全指南</h1><p>前两篇文章我们完成了环境搭建，也拆解了 ReActAgent 的核心推理循环。但有个细节不知道各位小伙伴注意到没有——<strong>无论是 ReActAgent 还是 HarnessAgent，创建方式都用的是 Builder 模式</strong>。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 你看，两种 Agent 都是 builder()</span>
<span class="token class-name">HarnessAgent</span> agent <span class="token operator">=</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;assistant&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">workspace</span><span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name">ReActAgent</span> agent <span class="token operator">=</span> <span class="token class-name">ReActAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;weather-agent&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token string">&quot;...&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">toolkit</span><span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>那么问题来了——为什么 AgentScope 2.0 选择了 Builder 模式，而不是构造函数、配置文件或者 Spring Bean？Builder 模式到底好在哪？怎么用 Builder 搭出一个&quot;能说会道还会思考&quot;的对话机器人？</p><p>今天这篇文章就彻底搞懂这三件事：<strong>Builder 模式的设计哲学、流式输出的完整姿势、以及思考模式（Thinking Mode）的正确打开方式</strong>。</p>`,8),d=p(`<h2 id="一、先聊聊-为什么是-builder-模式" tabindex="-1"><a class="header-anchor" href="#一、先聊聊-为什么是-builder-模式" aria-hidden="true">#</a> 一、先聊聊：为什么是 Builder 模式？</h2><p>一般来讲，Java 开发者创建一个对象有四种常见方式：</p><table><thead><tr><th>方式</th><th>典型代码</th><th>问题</th></tr></thead><tbody><tr><td>构造函数</td><td><code>new Agent(name, model, sysPrompt, toolkit, ...)</code></td><td>参数一多就晕，顺序不能错</td></tr><tr><td>Setter 注入</td><td><code>agent.setName(); agent.setModel();</code></td><td>对象可能处于&quot;半构建&quot;状态</td></tr><tr><td>Spring Bean</td><td><code>@Bean</code> 注入</td><td>太重，而且 Agent 通常是动态创建的</td></tr><tr><td>配置文件</td><td><code>application.yml</code></td><td>灵活性差，运行时难以调整</td></tr></tbody></table><p>AgentScope 2.0 选了 Builder 模式，原因其实很简单——<strong>一个 Agent 的可配置项太多了，而且有大量的可选参数</strong>。</p><p>来看看一个完整的 HarnessAgent Builder 都有什么：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">HarnessAgent</span> agent <span class="token operator">=</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token comment">// ─── 必填项 ───</span>
        <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;agent-demo&quot;</span><span class="token punctuation">)</span>                          <span class="token comment">// Agent 名称</span>
        <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>                                <span class="token comment">// LLM 模型</span>

        <span class="token comment">// ─── 基础可选 ───</span>
        <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token string">&quot;你是一个有用的助手。&quot;</span><span class="token punctuation">)</span>             <span class="token comment">// 系统提示词</span>
        <span class="token punctuation">.</span><span class="token function">workspace</span><span class="token punctuation">(</span><span class="token class-name">Paths</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;.workspace&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>           <span class="token comment">// 工作区路径</span>

        <span class="token comment">// ─── 记忆与上下文 ───</span>
        <span class="token punctuation">.</span><span class="token function">memory</span><span class="token punctuation">(</span><span class="token class-name">MemoryConfig</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>                <span class="token comment">// 记忆配置</span>
                <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token string">&quot;openai:gpt-4.1-mini&quot;</span><span class="token punctuation">)</span>         <span class="token comment">// 可指定轻量模型做记忆</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">compaction</span><span class="token punctuation">(</span><span class="token class-name">CompactionConfig</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>        <span class="token comment">// 上下文压缩配置</span>
                <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token string">&quot;openai:gpt-4.1-mini&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">maxContextTokens</span><span class="token punctuation">(</span><span class="token number">8000</span><span class="token punctuation">)</span>                       <span class="token comment">// MEMORY 注入预算</span>
        <span class="token punctuation">.</span><span class="token function">additionalContextFile</span><span class="token punctuation">(</span><span class="token string">&quot;SOUL.md&quot;</span><span class="token punctuation">)</span>             <span class="token comment">// 额外上下文文件</span>
        <span class="token punctuation">.</span><span class="token function">additionalContextFile</span><span class="token punctuation">(</span><span class="token string">&quot;PREFERENCES.md&quot;</span><span class="token punctuation">)</span>

        <span class="token comment">// ─── 技能与工具 ───</span>
        <span class="token punctuation">.</span><span class="token function">toolkit</span><span class="token punctuation">(</span>toolkit<span class="token punctuation">)</span>                             <span class="token comment">// 工具注册中心</span>
        <span class="token punctuation">.</span><span class="token function">skillRepository</span><span class="token punctuation">(</span>fileSystemSkillRepository<span class="token punctuation">)</span>   <span class="token comment">// 技能仓库</span>

        <span class="token comment">// ─── 高级能力 ───</span>
        <span class="token punctuation">.</span><span class="token function">enablePlanMode</span><span class="token punctuation">(</span><span class="token punctuation">)</span>                             <span class="token comment">// 开启计划模式</span>
        <span class="token punctuation">.</span><span class="token function">planFileDirectory</span><span class="token punctuation">(</span><span class="token string">&quot;plans&quot;</span><span class="token punctuation">)</span>                   <span class="token comment">// 计划文件目录</span>

        <span class="token comment">// ─── 中间件 ───</span>
        <span class="token punctuation">.</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">LoggingMiddleware</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>           <span class="token comment">// 注册中间件</span>

        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                     <span class="token comment">// 最终构建</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看到没？<strong>十几个配置项，大部分都是可选的</strong>。如果用构造函数，你得写出 N 个重载版本——这画面太美我不敢看。</p><p>而 Builder 模式的精髓就在于：</p><blockquote><p><strong>用链式调用的方式，把&quot;我要什么&quot;说清楚，不用关心&quot;怎么拼起来&quot;。</strong></p></blockquote><p>这对 Agent 框架来说尤其重要——Agent 是一个&quot;活的&quot;对象，它需要的不是&quot;new 出来&quot;的那一刻就定死一切，而是&quot;可以灵活组合各种能力&quot;的构造方式。Builder 模式正好满足了这种<strong>高可配、高可读、高安全性</strong>的需求。</p><h3 id="_1-跟-spring-ai-对比一下" tabindex="-1"><a class="header-anchor" href="#_1-跟-spring-ai-对比一下" aria-hidden="true">#</a> 1. 跟 Spring AI 对比一下</h3><p>用过 Spring AI 的小伙伴应该知道，它的 Agent 创建方式更&quot;Spring 化&quot;——通过 <code>@Bean</code> 注入各种组件：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// Spring AI 的方式：依赖注入</span>
<span class="token annotation punctuation">@Bean</span>
<span class="token keyword">public</span> <span class="token class-name">ChatClient</span> <span class="token function">chatClient</span><span class="token punctuation">(</span><span class="token class-name">ChatClient<span class="token punctuation">.</span>Builder</span> builder<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> builder
            <span class="token punctuation">.</span><span class="token function">defaultSystem</span><span class="token punctuation">(</span><span class="token string">&quot;你是一个助手&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>AgentScope 的选择是<strong>纯 Java Builder</strong>，不绑定 Spring 容器。这意味着——<strong>你可以在任何地方创建 Agent，不一定要在 Spring 上下文里</strong>。对于非 Spring 项目、或者需要动态创建 Agent 的场景来说，这个设计更轻量、更灵活。</p><p>当然，如果你项目本身就是 Spring Boot，直接把构建好的 Agent 注册为 <code>@Bean</code> 也完全没问题。</p><h2 id="二、builder-模式的核心构建块拆解" tabindex="-1"><a class="header-anchor" href="#二、builder-模式的核心构建块拆解" aria-hidden="true">#</a> 二、Builder 模式的核心构建块拆解</h2><p>上面那张配置清单看着有点多，我们来一个个拆解。我把配置项按用途分成四个组，方便理解和记忆。</p><h3 id="_1-基础三件套-name-model-sysprompt" tabindex="-1"><a class="header-anchor" href="#_1-基础三件套-name-model-sysprompt" aria-hidden="true">#</a> 1. 基础三件套：name / model / sysPrompt</h3><p>这三个是 Agent 的&quot;身份证&quot;，缺任何一个 Agent 都跑不起来：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * name —— Agent 的身份标识
 * - 出现在工作区目录、日志、事件 source 字段中
 * - 在多 Agent 协作中用于区分不同的 Agent
 * - 建议用英文短词：assistant、coder、reviewer 等
 */</span>
<span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;assistant&quot;</span><span class="token punctuation">)</span>

<span class="token doc-comment comment">/**
 * model —— Agent 的大脑
 * - 可以是 ModelRegistry 解析的字符串：&quot;deepseek:deepseek-chat&quot;
 * - 也可以是直接构建的 Model 对象：OpenAIChatModel.builder()...build()
 * - 推荐用字符串方式，通过 ModelRegistry 统一管理
 */</span>
<span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token string">&quot;deepseek:deepseek-chat&quot;</span><span class="token punctuation">)</span>

<span class="token doc-comment comment">/**
 * sysPrompt —— Agent 的人设
 * - 系统提示词，告诉 Agent&quot;你是谁、该怎么做&quot;
 * - 对于 HarnessAgent，sysPrompt 是可选的（工作区里可以放 AGENTS.md）
 * - 对于 ReActAgent，sysPrompt 是必须的
 */</span>
<span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token string">&quot;你是一个资深的 Java 开发工程师，擅长代码审查和性能优化。&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-可选但推荐-workspace-memory-toolkit" tabindex="-1"><a class="header-anchor" href="#_2-可选但推荐-workspace-memory-toolkit" aria-hidden="true">#</a> 2. 可选但推荐：workspace / memory / toolkit</h3><p>这三个&quot;开箱即用&quot;很爽，但配好了战斗力翻倍：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * workspace —— Agent 的&quot;家&quot;
 * - 工作区路径，如果不配默认为 $<span class="token punctuation">{</span>user.dir<span class="token punctuation">}</span>/.agentscope/workspace
 * - Agent 的人设、记忆、技能、会话日志都存这里
 * - 同一个 workspace + 同一个 userId + 同一个 sessionId → 跨会话记忆恢复
 */</span>
<span class="token punctuation">.</span><span class="token function">workspace</span><span class="token punctuation">(</span><span class="token class-name">Paths</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;.agentscope/workspace&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>

<span class="token doc-comment comment">/**
 * memory —— Agent 的&quot;长期记忆&quot;
 * - 用单独的模型（通常是轻量模型）来处理记忆的存取
 * - 主模型做复杂推理，记忆模型做上下文管理——分工明确
 */</span>
<span class="token punctuation">.</span><span class="token function">memory</span><span class="token punctuation">(</span><span class="token class-name">MemoryConfig</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token string">&quot;openai:gpt-4.1-mini&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>

<span class="token doc-comment comment">/**
 * toolkit —— Agent 的&quot;工具箱&quot;
 * - 注册 @Tool 注解标注的 Java 方法
 * - 也可以注册 MCP 客户端（对接外部服务）
 */</span>
<span class="token punctuation">.</span><span class="token function">toolkit</span><span class="token punctuation">(</span>toolkit<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-进阶能力-enableplanmode-middleware" tabindex="-1"><a class="header-anchor" href="#_3-进阶能力-enableplanmode-middleware" aria-hidden="true">#</a> 3. 进阶能力：enablePlanMode / middleware</h3><p>这两个是&quot;高手选项&quot;，让 Agent 具备规划和可观测性：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * enablePlanMode —— 让 Agent 先想后做
 * - 安装 PlanEnter / PlanExit / PlanLoad 三个元工具
 * - Agent 会在复杂任务前先写计划，确认后再执行
 * - 适合多步骤、高风险的场景
 */</span>
<span class="token punctuation">.</span><span class="token function">enablePlanMode</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">.</span><span class="token function">planFileDirectory</span><span class="token punctuation">(</span><span class="token string">&quot;plans&quot;</span><span class="token punctuation">)</span>   <span class="token comment">// 计划文件存放目录</span>

<span class="token doc-comment comment">/**
 * middleware —— Agent 的&quot;中间件&quot;
 * - 类似 Spring 的 Filter / Interceptor
 * - 5 个核心钩子：onAgent / onReasoning / onActing / onModelCall / onSystemPrompt
 * - 用于日志、限流、重试、监控等横切逻辑
 */</span>
<span class="token punctuation">.</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">LoggingMiddleware</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
<span class="token punctuation">.</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">RateLimitMiddleware</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在这里，简单提一下Middleware，是在不修改 agent 或 model 代码的前提下，向 agent 执行流程中的关键位置注入自定义逻辑（日志、追踪、输入改写、访问控制等）的机制。</p><p>简单来说，在我们希望对大模型的调用过程进行检测管控时，就可以通过Middleware来进行管控，这就是我们自己来控制大模型调用执行最佳控制手段。</p><h3 id="_4-上下文增强-additionalcontextfile-maxcontexttokens" tabindex="-1"><a class="header-anchor" href="#_4-上下文增强-additionalcontextfile-maxcontexttokens" aria-hidden="true">#</a> 4. 上下文增强：additionalContextFile / maxContextTokens</h3><p>这两个是做&quot;知识注入&quot;的关键：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * additionalContextFile —— 额外上下文文件
 * - 可以是工作区相对路径的任意 Markdown 文件
 * - 内容会在每次对话时内联到系统提示词中
 * - 适合放&quot;始终有效的背景知识&quot;
 */</span>
<span class="token punctuation">.</span><span class="token function">additionalContextFile</span><span class="token punctuation">(</span><span class="token string">&quot;SOUL.md&quot;</span><span class="token punctuation">)</span>             <span class="token comment">// Agent 的&quot;灵魂设定&quot;</span>
<span class="token punctuation">.</span><span class="token function">additionalContextFile</span><span class="token punctuation">(</span><span class="token string">&quot;PRODUCT_RULES.md&quot;</span><span class="token punctuation">)</span>    <span class="token comment">// 产品规则</span>
<span class="token punctuation">.</span><span class="token function">additionalContextFile</span><span class="token punctuation">(</span><span class="token string">&quot;CODING_STANDARDS.md&quot;</span><span class="token punctuation">)</span> <span class="token comment">// 编码规范</span>

<span class="token doc-comment comment">/**
 * maxContextTokens —— 控制 MEMORY 注入的上限
 * - 默认值取决于模型上下文窗口
 * - 设得太小：记忆不够用；设得太大：模型被历史淹没
 * - 建议设为模型最大上下文的 60-70%
 */</span>
<span class="token punctuation">.</span><span class="token function">maxContextTokens</span><span class="token punctuation">(</span><span class="token number">8000</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>踩坑提醒</strong>：<code>additionalContextFile</code> 不是越多越好。每个文件都会在每次对话中注入到系统提示词里，如果文件太多太大，Token 消耗会飞速增长。建议只放 2-3 个最核心的文件，详细的技能知识通过 SkillRepository 按需加载。</p></blockquote><h2 id="三、你的第一个-真正-的对话机器人" tabindex="-1"><a class="header-anchor" href="#三、你的第一个-真正-的对话机器人" aria-hidden="true">#</a> 三、你的第一个&quot;真正&quot;的对话机器人</h2><p>前两篇的 demo 都是一次性运行，今天我们来构建一个<strong>可以持续对话的基础聊天机器人</strong>——支持多轮对话保持上下文、流式打字效果输出、以及实时展示思考过程。</p><h3 id="_1-构建一个支持多轮对话的-bot" tabindex="-1"><a class="header-anchor" href="#_1-构建一个支持多轮对话的-bot" aria-hidden="true">#</a> 1. 构建一个支持多轮对话的 Bot</h3><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">package</span> <span class="token namespace">com<span class="token punctuation">.</span>example</span><span class="token punctuation">;</span>

<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>core<span class="token punctuation">.</span></span><span class="token class-name">ReActAgent</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>core<span class="token punctuation">.</span>message<span class="token punctuation">.</span></span><span class="token class-name">Msg</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>core<span class="token punctuation">.</span>message<span class="token punctuation">.</span></span><span class="token class-name">UserMessage</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>extensions<span class="token punctuation">.</span>model<span class="token punctuation">.</span>openai<span class="token punctuation">.</span></span><span class="token class-name">OpenAIChatModel</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>extensions<span class="token punctuation">.</span>model<span class="token punctuation">.</span>openai<span class="token punctuation">.</span></span><span class="token class-name">OpenAIChatFormatter</span></span><span class="token punctuation">;</span>

<span class="token keyword">import</span> <span class="token import"><span class="token namespace">java<span class="token punctuation">.</span>util<span class="token punctuation">.</span></span><span class="token class-name">Scanner</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">ChatBotDemo</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 1. 构建模型（开启流式模式）</span>
        <span class="token class-name">OpenAIChatModel</span> model <span class="token operator">=</span> <span class="token class-name">OpenAIChatModel</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">apiKey</span><span class="token punctuation">(</span><span class="token class-name">EnvUtil</span><span class="token punctuation">.</span><span class="token function">getSiliconApiKey</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">baseUrl</span><span class="token punctuation">(</span><span class="token string">&quot;https://api.siliconflow.cn&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">endpointPath</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/chat/completions&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">modelName</span><span class="token punctuation">(</span><span class="token string">&quot;Qwen/Qwen2.5-7B-Instruct&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span>                    <span class="token comment">// ← 流式输出开关</span>
                <span class="token punctuation">.</span><span class="token function">formatter</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">OpenAIChatFormatter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 2. 构建 Agent（纯对话，不需要工具）</span>
        <span class="token class-name">ReActAgent</span> agent <span class="token operator">=</span> <span class="token class-name">ReActAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;chat-bot&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token string">&quot;你是一个友善、风趣的聊天伙伴。&quot;</span> <span class="token operator">+</span>
                        <span class="token string">&quot;你会记住对话历史，基于上下文回答问题。&quot;</span> <span class="token operator">+</span>
                        <span class="token string">&quot;回答简洁但信息量充足。&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">maxIters</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span>                     <span class="token comment">// 纯对话不需要太多迭代</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;╔════════════════════════════════════╗&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;║      🤖 一灰灰聊天机器人 v1.0       ║&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;║  输入 &#39;exit&#39; 退出，输入 &#39;clear&#39; 清空  ║&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;╚════════════════════════════════════╝\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 3. 多轮对话循环</span>
        <span class="token keyword">try</span> <span class="token punctuation">(</span><span class="token class-name">Scanner</span> scanner <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Scanner</span><span class="token punctuation">(</span><span class="token class-name">System</span><span class="token punctuation">.</span>in<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string">&quot;🙋 你: &quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token class-name">String</span> input <span class="token operator">=</span> scanner<span class="token punctuation">.</span><span class="token function">nextLine</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token string">&quot;exit&quot;</span><span class="token punctuation">.</span><span class="token function">equalsIgnoreCase</span><span class="token punctuation">(</span>input<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;👋 再见！&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">break</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token string">&quot;clear&quot;</span><span class="token punctuation">.</span><span class="token function">equalsIgnoreCase</span><span class="token punctuation">(</span>input<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    agent <span class="token operator">=</span> <span class="token class-name">ReActAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                            <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;chat-bot&quot;</span><span class="token punctuation">)</span>
                            <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token string">&quot;你是一个友善、风趣的聊天伙伴。&quot;</span> <span class="token operator">+</span>
                                    <span class="token string">&quot;你会记住对话历史，基于上下文回答问题。&quot;</span> <span class="token operator">+</span>
                                    <span class="token string">&quot;回答简洁但信息量充足。&quot;</span><span class="token punctuation">)</span>
                            <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>
                            <span class="token punctuation">.</span><span class="token function">maxIters</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span>
                            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// ← 重新创建 Agent 清空上下文</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;🧹 对话历史已清空！\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">continue</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>

                <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string">&quot;🤖 Bot: &quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token comment">// 流式输出——逐字打印</span>
                agent<span class="token punctuation">.</span><span class="token function">streamEvents</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserMessage</span><span class="token punctuation">(</span>input<span class="token punctuation">)</span><span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">doOnNext</span><span class="token punctuation">(</span>event <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                            <span class="token keyword">if</span> <span class="token punctuation">(</span>event<span class="token punctuation">.</span><span class="token function">getType</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token class-name">AgentEventType</span><span class="token punctuation">.</span><span class="token constant">TEXT_BLOCK_DELTA</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                                <span class="token class-name">String</span> delta <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">TextBlockDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                                <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span>delta<span class="token punctuation">)</span><span class="token punctuation">;</span>
                            <span class="token punctuation">}</span>
                        <span class="token punctuation">}</span><span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">blockLast</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>运行效果：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>╔════════════════════════════════════╗
║      🤖 一灰灰聊天机器人 v1.0       ║
║  输入 <span class="token string">&#39;exit&#39;</span> 退出，输入 <span class="token string">&#39;clear&#39;</span> 清空  ║
╚════════════════════════════════════╝

🙋 你: 你好！我是第一次来聊天。
🤖 Bot: 你好！很高兴遇见你。首蓿次聊天也可以很有趣呢。有什么想聊的话题吗？

🙋 你: 我刚才说了什么？
🤖 Bot: 你刚才说你是第一次来聊天。很高兴遇见你첫번째 대화吆，注意放松哦。

🙋 你: 那你能记住我名字吗？叫一灰灰。w
🤖 Bot: 当然可以了，叫我一灰灰，很高兴认识你！有什么想聊聊的话题吗？

🙋 你: 我是谁
🤖 Bot: 你在之前的对话中说叫“一灰灰”。如果你有不同的名字，可以告诉我哦！

🙋 你: <span class="token function">clear</span>
🧹 对话历史已清空！

🙋 你: 你知道我叫什么吗
🤖 Bot: 你叫什么名字呢？我可以记住你的的名字哦。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="https://imgbed.ppai.top/file/1784778470197_image.png" alt="image.png" tabindex="0" loading="lazy"><figcaption>image.png</figcaption></figure><p>有没有发现神奇的地方？<strong>Agent 自己就记住了上下文</strong>——第二轮它记得第一轮说了什么，第三轮它记住了&quot;一灰灰&quot;这个名字。而&quot;clear&quot;之后重新构建 Agent，它就不记得之前的对话了。</p><p>这是因为 ReActAgent 的 <code>call()</code> 方法内部自动维护了上下文队列。每次调用时，用户消息和 Agent 回复都会追加到队列中，模型&quot;看到&quot;的是完整的对话历史。这也是为什么纯对话场景下 <code>maxIters</code> 设成 3 就够了——没有工具调用，Agent 不需要多次迭代。</p><h3 id="_2-没有-session-持久化的-记忆-有个坑" tabindex="-1"><a class="header-anchor" href="#_2-没有-session-持久化的-记忆-有个坑" aria-hidden="true">#</a> 2. 没有 Session 持久化的&quot;记忆&quot;有个坑</h3><p>注意上面这个 demo，Agent 的记忆只在内存中生效——<strong>进程重启后，对话就丢了</strong>。</p><p>如果想让 Agent 跨进程重启保持记忆，需要配置 <code>stateStore</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// HarnessAgent 的方式——工作区自动管理持久化</span>
<span class="token class-name">HarnessAgent</span> agent <span class="token operator">=</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;persistent-bot&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">workspace</span><span class="token punctuation">(</span><span class="token class-name">Paths</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;.agentscope/sessions&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 第二轮起，同 userId + sessionId 就会自动加载历史</span>
<span class="token class-name">String</span> reply <span class="token operator">=</span> agent<span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span>
        <span class="token keyword">new</span> <span class="token class-name">UserMessage</span><span class="token punctuation">(</span><span class="token string">&quot;我刚才说了什么？&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
        <span class="token class-name">RuntimeContext</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">userId</span><span class="token punctuation">(</span><span class="token string">&quot;yihuihui&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">sessionId</span><span class="token punctuation">(</span><span class="token string">&quot;chat-001&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">block</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这块在上一篇讲 ReActAgent 时已经详细对比过了，这里不再赘述。</p><h2 id="四、流式输出深入-不仅仅是-逐字打印" tabindex="-1"><a class="header-anchor" href="#四、流式输出深入-不仅仅是-逐字打印" aria-hidden="true">#</a> 四、流式输出深入：不仅仅是&quot;逐字打印&quot;</h2><p>前两篇文章我们都用了 <code>streamEvents()</code>，但只是简单处理了 <code>TEXT_BLOCK_DELTA</code> 事件。实际上 AgentScope 2.0 的流式事件系统远不止于此——它覆盖了 Agent 执行的<strong>整个生命周期</strong>。</p><h3 id="_1-你需要知道的-6-类核心事件" tabindex="-1"><a class="header-anchor" href="#_1-你需要知道的-6-类核心事件" aria-hidden="true">#</a> 1. 你需要知道的 6 类核心事件</h3><p>我把最常用的六类事件整理成了下表：</p><table><thead><tr><th>事件类型</th><th>触发时机</th><th>典型用途</th></tr></thead><tbody><tr><td><code>AgentStartEvent</code></td><td>Agent 开始处理请求</td><td>显示&quot;思考中...&quot;的加载状态</td></tr><tr><td><code>TextBlockDeltaEvent</code></td><td>文本逐块生成</td><td>流式打字效果</td></tr><tr><td><code>ThinkingBlockStartEvent</code></td><td>模型开始思考（思维链）</td><td>显示&quot;🤔 思考中...&quot;</td></tr><tr><td><code>ThinkingBlockDeltaEvent</code></td><td>思考内容逐块生成</td><td>实时展示推理过程</td></tr><tr><td><code>ThinkingBlockEndEvent</code></td><td>思考结束</td><td>关闭思考气泡</td></tr><tr><td><code>ToolCallStartEvent</code></td><td>Agent 决定调用工具</td><td>显示&quot;🔧 正在查资料...&quot;</td></tr><tr><td><code>ToolResultEndEvent</code></td><td>工具执行完成</td><td>工具结果已经返回</td></tr><tr><td><code>AgentEndEvent</code></td><td>Agent 处理完成</td><td>结束流式输出</td></tr></tbody></table><h3 id="_2-一个完整的流式监听器" tabindex="-1"><a class="header-anchor" href="#_2-一个完整的流式监听器" aria-hidden="true">#</a> 2. 一个完整的流式监听器</h3><p>把上面这些事件组合起来，就能实现&quot;ChatGPT 级别&quot;的流式展示效果：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code>agent<span class="token punctuation">.</span><span class="token function">streamEvents</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserMessage</span><span class="token punctuation">(</span><span class="token string">&quot;介绍一下 Builder 模式的优缺点&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">doOnNext</span><span class="token punctuation">(</span>event <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
            <span class="token keyword">switch</span> <span class="token punctuation">(</span>event<span class="token punctuation">.</span><span class="token function">getType</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token keyword">case</span> <span class="token constant">AGENT_START</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// Agent 开始处理</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n🤔 正在思考...&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">THINKING_BLOCK_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 思考过程——灰色显示思维链</span>
                    <span class="token class-name">String</span> thought <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ThinkingBlockDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string">&quot;\\u001B[90m&quot;</span> <span class="token operator">+</span> thought <span class="token operator">+</span> <span class="token string">&quot;\\u001B[0m&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 灰色</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">THINKING_BLOCK_END</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 思考结束，准备输出</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n\\u001B[90m━━━ 思考完毕，开始回答 ━━━\\u001B[0m\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">TEXT_BLOCK_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 正式回答——正常颜色流式输出</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">TextBlockDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">TOOL_CALL_START</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// Agent 调用工具</span>
                    <span class="token class-name">String</span> toolName <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ToolCallStartEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getToolCallName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n🔧 [调用工具] &quot;</span> <span class="token operator">+</span> toolName<span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">TOOL_CALL_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 工具执行传参</span>
                    <span class="token class-name">String</span> toolInput <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ToolCallDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;➡️  参数: &quot;</span> <span class="token operator">+</span> toolInput<span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">TOOL_RESULT_TEXT_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 工具执行结果流式输出</span>
                    <span class="token class-name">String</span> toolOutput <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ToolResultTextDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string">&quot;➡️  返回: &quot;</span><span class="token operator">+</span> toolOutput<span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">TOOL_RESULT_END</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 工具执行完毕</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n✅ [工具完成]&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">case</span> <span class="token constant">AGENT_END</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 全部处理完成</span>
                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n\\n✅ 完成！&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
                <span class="token keyword">default</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token comment">// 其他事件忽略</span>
                <span class="token punctuation">}</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">blockLast</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>运行效果：</p><figure><img src="https://imgbed.ppai.top/file/1784779079889_image.png" alt="image.png" tabindex="0" loading="lazy"><figcaption>image.png</figcaption></figure><blockquote><p><strong>注意</strong>：上面的 <code>THINKING_BLOCK_*</code> 事件对应的是模型的&quot;思维链&quot;（Chain of Thought）内容。不是所有模型都支持思维链输出——像 DeepSeek-R1、QwQ-32B 这类推理模型会输出完整的思考过程，而普通模型可能只会输出简短的中间推理。</p></blockquote><h3 id="_3-在-web-应用中对接流式输出" tabindex="-1"><a class="header-anchor" href="#_3-在-web-应用中对接流式输出" aria-hidden="true">#</a> 3. 在 Web 应用中对接流式输出</h3><p>如果你的 Agent 跑在 Spring Boot 后端，想把流式输出推送到前端，最简单的方式是用 <strong>WebSocket + Server-Sent Events (SSE)</strong>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// Spring Boot Controller —— SSE 端点</span>
<span class="token annotation punctuation">@GetMapping</span><span class="token punctuation">(</span>path <span class="token operator">=</span> <span class="token string">&quot;/api/chat/stream&quot;</span><span class="token punctuation">,</span> produces <span class="token operator">=</span> <span class="token class-name">MediaType</span><span class="token punctuation">.</span><span class="token constant">TEXT_EVENT_STREAM_VALUE</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token class-name">Flux</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">ServerSentEvent</span><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> <span class="token function">streamChat</span><span class="token punctuation">(</span><span class="token annotation punctuation">@RequestParam</span> <span class="token class-name">String</span> message<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> agent<span class="token punctuation">.</span><span class="token function">streamEvents</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserMessage</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span>event <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                <span class="token class-name">String</span> type <span class="token operator">=</span> event<span class="token punctuation">.</span><span class="token function">getType</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token class-name">String</span> data <span class="token operator">=</span> <span class="token keyword">switch</span> <span class="token punctuation">(</span>event<span class="token punctuation">.</span><span class="token function">getType</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token keyword">case</span> <span class="token constant">TEXT_BLOCK_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">TextBlockDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">case</span> <span class="token constant">THINKING_BLOCK_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ThinkingBlockDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">case</span> <span class="token constant">TOOL_CALL_START</span> <span class="token operator">-&gt;</span> <span class="token string">&quot;[工具] &quot;</span> <span class="token operator">+</span>
                            <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ToolCallStartEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getToolCallName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">case</span> <span class="token constant">AGENT_END</span> <span class="token operator">-&gt;</span> <span class="token string">&quot;[DONE]&quot;</span><span class="token punctuation">;</span>
                    <span class="token keyword">default</span> <span class="token operator">-&gt;</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span><span class="token punctuation">;</span>
                <span class="token keyword">if</span> <span class="token punctuation">(</span>data <span class="token operator">==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span>

                <span class="token keyword">return</span> <span class="token class-name">ServerSentEvent</span><span class="token punctuation">.</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">event</span><span class="token punctuation">(</span>type<span class="token punctuation">.</span><span class="token function">toLowerCase</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">data</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token class-name">Objects</span><span class="token operator">::</span><span class="token function">nonNull</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>前端配合 EventSource 或者 fetch + ReadableStream 就能实现类似 ChatGPT 的打字效果。这块的具体实现我们放到后续&quot;企业级工程化&quot;章节再展开。</p><h2 id="五、思考模式-thinking-mode-的正确打开姿势" tabindex="-1"><a class="header-anchor" href="#五、思考模式-thinking-mode-的正确打开姿势" aria-hidden="true">#</a> 五、思考模式（Thinking Mode）的正确打开姿势</h2><p>前面提到了 <code>ThinkingBlock</code> 事件，但你可能好奇——这个思考内容到底是怎么来的？是不是所有模型都能输出思考过程？怎么让 Agent 展示出&quot;推理链&quot;？</p><h3 id="_1-两种-思考-的区别" tabindex="-1"><a class="header-anchor" href="#_1-两种-思考-的区别" aria-hidden="true">#</a> 1. 两种&quot;思考&quot;的区别</h3><p>在 AgentScope 2.0 中，有两层含义的&quot;思考&quot;：</p><table><thead><tr><th>层面</th><th>对应事件</th><th>说明</th></tr></thead><tbody><tr><td><strong>ReAct 推理循环</strong></td><td><code>ReasoningChunkEvent</code></td><td>Agent 框架层面的&quot;下一步该做什么&quot;的推理</td></tr><tr><td><strong>模型思维链</strong></td><td><code>ThinkingBlock*Event</code></td><td>LLM 模型内部的&quot;思考过程&quot;（如 DeepSeek-R1 的思维链）</td></tr></tbody></table><p>简单来讲：</p><ul><li><strong>ReAct 推理</strong> = Agent 框架在循环中决定&quot;是继续思考还是调用工具&quot;</li><li><strong>模型思维链</strong> = LLM 在输出最终答案前，内部进行的推理过程</li></ul><p>两者的关系可以理解为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>用户提问 → Agent 框架收到 → ReAct 循环开始
    → LLM 开始推理（思维链：ThinkingBlock 事件）
    → LLM 决定调用工具（ToolCallStart 事件）
    → 工具执行（ToolResult 事件）
    → LLM 继续推理（又一个 ThinkingBlock 事件）
    → LLM 输出最终回答（TextBlock 事件）
    → ReAct 循环结束
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-什么时候能看到-thinkingblock" tabindex="-1"><a class="header-anchor" href="#_2-什么时候能看到-thinkingblock" aria-hidden="true">#</a> 2. 什么时候能看到 ThinkingBlock？</h3><p>关键在于<strong>模型本身是否支持思维链输出</strong>。目前主流的推理模型（reasoning models）都支持：</p><table><thead><tr><th>模型</th><th>是否输出思维链</th><th>备注</th></tr></thead><tbody><tr><td>DeepSeek-R1</td><td>✅</td><td>完整开放思维链</td></tr><tr><td>DeepSeek-R1-Distill</td><td>✅</td><td>蒸馏版也支持</td></tr><tr><td>QwQ-32B</td><td>✅</td><td>阿里通义推理模型</td></tr><tr><td>QwQ-Plus</td><td>✅</td><td>增强版</td></tr><tr><td>GPT-4o</td><td>⚠️ 部分</td><td>o 系列模型有内部思维链</td></tr><tr><td>Claude Sonnet 4.5</td><td>❌</td><td>不暴露思维链</td></tr><tr><td>普通模型 (Qwen2.5 等)</td><td>⚠️ 有限</td><td>需要 prompt 引导</td></tr></tbody></table><p>如果你用的是 DeepSeek-R1 这类推理模型，<strong>无需任何额外配置</strong>，<code>streamEvents()</code> 就会自动收到 <code>ThinkingBlock</code> 事件。</p><h3 id="_3-如果模型不支持思维链-自己动手造一个" tabindex="-1"><a class="header-anchor" href="#_3-如果模型不支持思维链-自己动手造一个" aria-hidden="true">#</a> 3. 如果模型不支持思维链？自己动手造一个</h3><p>如果你用的是 Qwen2.5、GLM-4 这类不原生输出思维链的模型，也可以通过 prompt 技巧让 Agent&quot;模拟&quot;思考过程：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">ReActAgent</span> agent <span class="token operator">=</span> <span class="token class-name">ReActAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;thinking-bot&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token triple-quoted-string string">&quot;&quot;&quot; 
                你是一个擅长&quot;边想边说&quot;的 AI 助手。
                
                在回答用户问题之前，请先进行内部推理。推理过程用以下格式包裹：
                
                &lt;thinking&gt;
                在这里写出你的推理过程、考虑的方案、对比的权衡
                &lt;/thinking&gt;
                
                推理完成后，再给出最终回答。
                
                示例：
                用户：Java 中 List 和 Set 有什么区别？
                &lt;thinking&gt;
                List 和 Set 都是 Collection 的子接口...
                它们的主要区别在于：List 是有序可重复的...
                用户可能想了解使用场景的选择...
                &lt;/thinking&gt;
                
                List 和 Set 的主要区别有以下几点：
                1. 有序性：...
                &quot;&quot;&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后在前端监听 <code>TEXT_BLOCK_DELTA</code>，检测到 <code>&lt;thinking&gt;</code> 标签就切换到&quot;思考模式&quot;渲染：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 一个简单的思考模式解析器</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">ThinkingModeParser</span> <span class="token punctuation">{</span>
    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Pattern</span> <span class="token constant">THINKING_PATTERN</span> <span class="token operator">=</span>
            <span class="token class-name">Pattern</span><span class="token punctuation">.</span><span class="token function">compile</span><span class="token punctuation">(</span><span class="token string">&quot;&lt;thinking&gt;(.*?)&lt;/thinking&gt;&quot;</span><span class="token punctuation">,</span> <span class="token class-name">Pattern</span><span class="token punctuation">.</span><span class="token constant">DOTALL</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Segment</span><span class="token punctuation">&gt;</span></span> <span class="token function">parse</span><span class="token punctuation">(</span><span class="token class-name">String</span> text<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Segment</span><span class="token punctuation">&gt;</span></span> segments <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayList</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">Matcher</span> matcher <span class="token operator">=</span> <span class="token constant">THINKING_PATTERN</span><span class="token punctuation">.</span><span class="token function">matcher</span><span class="token punctuation">(</span>text<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">int</span> lastEnd <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>

        <span class="token keyword">while</span> <span class="token punctuation">(</span>matcher<span class="token punctuation">.</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token comment">// 思考之前的文本（如果有）</span>
            <span class="token keyword">if</span> <span class="token punctuation">(</span>matcher<span class="token punctuation">.</span><span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> lastEnd<span class="token punctuation">)</span> <span class="token punctuation">{</span>
                segments<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Segment</span><span class="token punctuation">(</span>
                        text<span class="token punctuation">.</span><span class="token function">substring</span><span class="token punctuation">(</span>lastEnd<span class="token punctuation">,</span> matcher<span class="token punctuation">.</span><span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                        <span class="token class-name">SegmentType</span><span class="token punctuation">.</span><span class="token constant">TEXT</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
            <span class="token comment">// 思考内容</span>
            segments<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Segment</span><span class="token punctuation">(</span>matcher<span class="token punctuation">.</span><span class="token function">group</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">SegmentType</span><span class="token punctuation">.</span><span class="token constant">THINKING</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            lastEnd <span class="token operator">=</span> matcher<span class="token punctuation">.</span><span class="token function">end</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token comment">// 剩余文本</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>lastEnd <span class="token operator">&lt;</span> text<span class="token punctuation">.</span><span class="token function">length</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            segments<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Segment</span><span class="token punctuation">(</span>text<span class="token punctuation">.</span><span class="token function">substring</span><span class="token punctuation">(</span>lastEnd<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">SegmentType</span><span class="token punctuation">.</span><span class="token constant">TEXT</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">return</span> segments<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">enum</span> <span class="token class-name">SegmentType</span> <span class="token punctuation">{</span> <span class="token constant">TEXT</span><span class="token punctuation">,</span> <span class="token constant">THINKING</span> <span class="token punctuation">}</span>
    <span class="token keyword">record</span> <span class="token class-name">Segment</span><span class="token punctuation">(</span><span class="token class-name">String</span> content<span class="token punctuation">,</span> <span class="token class-name">SegmentType</span> type<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>注意</strong>：用 prompt 模拟的思维链和模型原生的 ThinkingBlock 有一个本质区别——<strong>原生 ThinkingBlock 事件在事件流中是独立的事件类型，可以被 <code>THINKING_BLOCK_DELTA</code> 单独捕获</strong>。而 prompt 模拟的思维链只是普通文本，你需要自己解析。效果上原生方式更优雅，prompt 方式更通用。</p></blockquote><h3 id="_4-实战-带思考流的-深度搜索-对话机器人" tabindex="-1"><a class="header-anchor" href="#_4-实战-带思考流的-深度搜索-对话机器人" aria-hidden="true">#</a> 4. 实战：带思考流的&quot;深度搜索&quot;对话机器人</h3><p>把上面的知识点串起来，我们来构建一个&quot;高端大气上档次&quot;的对话机器人——它会在回答问题前先展示思考过程，然后给出完整的回答，并且支持多轮对话：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">package</span> <span class="token namespace">com<span class="token punctuation">.</span>example</span><span class="token punctuation">;</span>

<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>example<span class="token punctuation">.</span>tools<span class="token punctuation">.</span></span><span class="token class-name">WebSearchTool</span></span><span class="token punctuation">;</span> <span class="token comment">// 假设有一个网页搜索工具</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>core<span class="token punctuation">.</span></span><span class="token class-name">ReActAgent</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>core<span class="token punctuation">.</span>event<span class="token punctuation">.</span></span><span class="token operator">*</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>core<span class="token punctuation">.</span>message<span class="token punctuation">.</span></span><span class="token class-name">UserMessage</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>core<span class="token punctuation">.</span>tool<span class="token punctuation">.</span></span><span class="token class-name">Toolkit</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>extensions<span class="token punctuation">.</span>model<span class="token punctuation">.</span>openai<span class="token punctuation">.</span></span><span class="token class-name">OpenAIChatModel</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">io<span class="token punctuation">.</span>agentscope<span class="token punctuation">.</span>extensions<span class="token punctuation">.</span>model<span class="token punctuation">.</span>openai<span class="token punctuation">.</span></span><span class="token class-name">OpenAIChatFormatter</span></span><span class="token punctuation">;</span>

<span class="token doc-comment comment">/**
 * 带思考流的深度对话机器人 Demo
 * 使用 DeepSeek-R1 等推理模型演示 ThinkingBlock 事件
 */</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DeepThinkingBot</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 使用推理模型（支持原生思维链）</span>
        <span class="token class-name">OpenAIChatModel</span> model <span class="token operator">=</span> <span class="token class-name">OpenAIChatModel</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">apiKey</span><span class="token punctuation">(</span><span class="token class-name">EnvUtil</span><span class="token punctuation">.</span><span class="token function">getSiliconApiKey</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">baseUrl</span><span class="token punctuation">(</span><span class="token string">&quot;https://api.siliconflow.cn&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">endpointPath</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/chat/completions&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">modelName</span><span class="token punctuation">(</span><span class="token string">&quot;Qwen/Qwen3-8B&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span>                    <span class="token comment">// ← 流式输出开关</span>
                <span class="token punctuation">.</span><span class="token function">formatter</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">OpenAIChatFormatter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">// ToolKit 添加网络搜索工具</span>
        <span class="token class-name">Toolkit</span> toolkit <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Toolkit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        toolkit<span class="token punctuation">.</span><span class="token function">registerTool</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">WebSearchTool</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>


        <span class="token comment">// 构建 Agent</span>
        <span class="token class-name">ReActAgent</span> agent <span class="token operator">=</span> <span class="token class-name">ReActAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;deep-thinker&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token string">&quot;你是一个深度思考助手。面对复杂问题，你会：\\n&quot;</span> <span class="token operator">+</span>
                        <span class="token string">&quot;1. 先展示完整的推理过程\\n&quot;</span> <span class="token operator">+</span>
                        <span class="token string">&quot;2. 如果需要实时信息，调用搜索工具\\n&quot;</span> <span class="token operator">+</span>
                        <span class="token string">&quot;3. 给出最终答案时引用推理中的关键结论&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">toolkit</span><span class="token punctuation">(</span>toolkit<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">maxIters</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 发起查询——展示完整思考 + 搜索 + 回答过程</span>
        agent<span class="token punctuation">.</span><span class="token function">streamEvents</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserMessage</span><span class="token punctuation">(</span>
                        <span class="token string">&quot;AgentScope Java 2.0 相比 1.x 版本有哪些重要的架构改进？ 官方文档地址为：https://java.agentscope.io/v2/zh/docs/index.html&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">doOnNext</span><span class="token punctuation">(</span>event <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token keyword">switch</span> <span class="token punctuation">(</span>event<span class="token punctuation">.</span><span class="token function">getType</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                        <span class="token keyword">case</span> <span class="token constant">AGENT_START</span> <span class="token operator">-&gt;</span> <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;🚀 开始分析问题...\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                        <span class="token keyword">case</span> <span class="token constant">THINKING_BLOCK_START</span> <span class="token operator">-&gt;</span> <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;┌─ 🤔 深度思考中 ─────────────────────┐&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                        <span class="token keyword">case</span> <span class="token constant">THINKING_BLOCK_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                            <span class="token comment">// 思考内容——用灰色斜体展示</span>
                            <span class="token class-name">String</span> thought <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ThinkingBlockDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                            <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string">&quot;\\u001B[90m&quot;</span> <span class="token operator">+</span> thought <span class="token operator">+</span> <span class="token string">&quot;\\u001B[0m&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                        <span class="token punctuation">}</span>

                        <span class="token keyword">case</span> <span class="token constant">THINKING_BLOCK_END</span> <span class="token operator">-&gt;</span> <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n└────────────────────────────────────┘\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                        <span class="token keyword">case</span> <span class="token constant">TOOL_CALL_START</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                            <span class="token class-name">String</span> toolName <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ToolCallStartEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getToolCallName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                            <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;🔍 [正在搜索] &quot;</span> <span class="token operator">+</span> toolName <span class="token operator">+</span> <span class="token string">&quot; ...&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                        <span class="token punctuation">}</span>

                        <span class="token keyword">case</span> <span class="token constant">TOOL_RESULT_TEXT_DELTA</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                            <span class="token class-name">String</span> toolOutput <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">ToolResultTextDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                            <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n\\u001B[90m━━━ 搜索结果 ━━━\\u001B[0m\\n&quot;</span> <span class="token operator">+</span> toolOutput<span class="token punctuation">)</span><span class="token punctuation">;</span>
                        <span class="token punctuation">}</span>

                        <span class="token keyword">case</span> <span class="token constant">TEXT_BLOCK_DELTA</span> <span class="token operator">-&gt;</span> <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">print</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">TextBlockDeltaEvent</span><span class="token punctuation">)</span> event<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDelta</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                        <span class="token keyword">case</span> <span class="token constant">AGENT_END</span> <span class="token operator">-&gt;</span> <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;\\n\\n✅ 分析完成！&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token punctuation">}</span>
                <span class="token punctuation">}</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">blockLast</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这段代码输出效果大概是这样的：</p><figure><img src="https://imgbed.ppai.top/file/1784787869224_image.png" alt="image.png" tabindex="0" loading="lazy"><figcaption>image.png</figcaption></figure><p>从上面的执行过程也可以看到，<strong>Agent 在发现自己的知识可能不完整时，主动去搜索了最新信息，然后继续推理</strong>，虽然我演示使用的工具搜索出现了查询抄手问题，但整体的执行链路还是完整的ReAct 循环 + 推理模型的完美配合——思考触发行动，行动结果反哺思考，最终给出答案。</p><h2 id="六、builder-模式的最佳实践与陷阱" tabindex="-1"><a class="header-anchor" href="#六、builder-模式的最佳实践与陷阱" aria-hidden="true">#</a> 六、Builder 模式的最佳实践与陷阱</h2><h3 id="_1-推荐-用工厂方法封装-builder" tabindex="-1"><a class="header-anchor" href="#_1-推荐-用工厂方法封装-builder" aria-hidden="true">#</a> 1. 推荐：用工厂方法封装 Builder</h3><p>直接在业务代码里写 <code>HarnessAgent.builder().xxx.build()</code> 虽然灵活，但会导致<strong>配置散落各处</strong>。推荐用工厂方法封装：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * Agent 工厂 —— 统一管理 Agent 的创建
 */</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">AgentFactory</span> <span class="token punctuation">{</span>

    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Model</span> <span class="token constant">DEFAULT_MODEL</span> <span class="token operator">=</span> <span class="token class-name">OpenAIChatModel</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">apiKey</span><span class="token punctuation">(</span><span class="token class-name">EnvUtil</span><span class="token punctuation">.</span><span class="token function">getSiliconApiKey</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">baseUrl</span><span class="token punctuation">(</span><span class="token string">&quot;https://api.siliconflow.cn&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">endpointPath</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/chat/completions&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">modelName</span><span class="token punctuation">(</span><span class="token string">&quot;Qwen/Qwen2.5-7B-Instruct&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">formatter</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">OpenAIChatFormatter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token doc-comment comment">/**
     * 创建纯对话机器人（无工具）
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">ReActAgent</span> <span class="token function">createChatBot</span><span class="token punctuation">(</span><span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">String</span> personality<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token class-name">ReActAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span><span class="token string">&quot;你是一个&quot;</span> <span class="token operator">+</span> personality <span class="token operator">+</span> <span class="token string">&quot;。&quot;</span> <span class="token operator">+</span>
                        <span class="token string">&quot;你会记住对话历史，基于上下文自然地回答问题。&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token constant">DEFAULT_MODEL</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">maxIters</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token doc-comment comment">/**
     * 创建带工具的智能助手
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">HarnessAgent</span> <span class="token function">createToolAgent</span><span class="token punctuation">(</span>
            <span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">String</span> prompt<span class="token punctuation">,</span> <span class="token class-name">Toolkit</span> toolkit<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span>prompt<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token constant">DEFAULT_MODEL</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">toolkit</span><span class="token punctuation">(</span>toolkit<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">workspace</span><span class="token punctuation">(</span><span class="token class-name">Paths</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;.agentscope&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;workspace&quot;</span><span class="token punctuation">,</span> name<span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token doc-comment comment">/**
     * 创建推理型 Agent（带思考模式 + 计划能力）
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">HarnessAgent</span> <span class="token function">createReasoningAgent</span><span class="token punctuation">(</span>
            <span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">String</span> prompt<span class="token punctuation">,</span> <span class="token class-name">Toolkit</span> toolkit<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">sysPrompt</span><span class="token punctuation">(</span>prompt <span class="token operator">+</span> <span class="token string">&quot;\\n在回答复杂问题前，请先展示你的思考过程。&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token constant">DEFAULT_MODEL</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">toolkit</span><span class="token punctuation">(</span>toolkit<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">enablePlanMode</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">workspace</span><span class="token punctuation">(</span><span class="token class-name">Paths</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;.agentscope&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;workspace&quot;</span><span class="token punctuation">,</span> name<span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token comment">// 使用 —— 一行代码创建 Agent</span>
<span class="token class-name">ReActAgent</span> chatBot <span class="token operator">=</span> <span class="token class-name">AgentFactory</span><span class="token punctuation">.</span><span class="token function">createChatBot</span><span class="token punctuation">(</span><span class="token string">&quot;assistant&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;友善的 Java 技术顾问&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">HarnessAgent</span> toolAgent <span class="token operator">=</span> <span class="token class-name">AgentFactory</span><span class="token punctuation">.</span><span class="token function">createToolAgent</span><span class="token punctuation">(</span><span class="token string">&quot;searcher&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span> toolkit<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-陷阱-builder-不是-用完即弃-的" tabindex="-1"><a class="header-anchor" href="#_2-陷阱-builder-不是-用完即弃-的" aria-hidden="true">#</a> 2. 陷阱：Builder 不是&quot;用完即弃&quot;的</h3><p>很多小伙伴会写出这样的代码：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// ❌ 错误用法：每次都构建新的 Model 对象</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">chat</span><span class="token punctuation">(</span><span class="token class-name">String</span> message<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">var</span> model <span class="token operator">=</span> <span class="token class-name">OpenAIChatModel</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">apiKey</span><span class="token punctuation">(</span><span class="token function">getApiKey</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">modelName</span><span class="token punctuation">(</span><span class="token string">&quot;qwen-plus&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">var</span> agent <span class="token operator">=</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;bot&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>       <span class="token comment">// ← 每次调用都新建 model</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    agent<span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserMessage</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">block</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Model 对象是线程安全的，可以复用</strong>。每次调用都新建 Model 会造成不必要的对象创建和连接开销。正确姿势是把 Model 提取为成员变量或者单例：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// ✅ 正确用法：Model 复用</span>
<span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Model</span> <span class="token constant">MODEL</span> <span class="token operator">=</span> <span class="token class-name">OpenAIChatModel</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">apiKey</span><span class="token punctuation">(</span><span class="token class-name">EnvUtil</span><span class="token punctuation">.</span><span class="token function">getApiKey</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">modelName</span><span class="token punctuation">(</span><span class="token string">&quot;qwen-plus&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">chat</span><span class="token punctuation">(</span><span class="token class-name">String</span> message<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">var</span> agent <span class="token operator">=</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;bot&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token constant">MODEL</span><span class="token punctuation">)</span>     <span class="token comment">// ← 复用</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    agent<span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserMessage</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">block</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-陷阱-builder-不会校验配置的正确性" tabindex="-1"><a class="header-anchor" href="#_3-陷阱-builder-不会校验配置的正确性" aria-hidden="true">#</a> 3. 陷阱：Builder 不会校验配置的正确性</h3><p>Builder 模式有一个&quot;先天弱点&quot;：<strong>所有的配置校验都是在 <code>build()</code> 方法中才执行的</strong>。这意味着你可能直到运行时才发现配置错了。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 编译通过，运行时炸了</span>
<span class="token class-name">HarnessAgent</span> agent <span class="token operator">=</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span>                          <span class="token comment">// 空名称</span>
        <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">Model</span><span class="token punctuation">)</span> <span class="token keyword">null</span><span class="token punctuation">)</span>               <span class="token comment">// 空模型</span>
        <span class="token punctuation">.</span><span class="token function">maxContextTokens</span><span class="token punctuation">(</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span>              <span class="token comment">// 负数 Token</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                          <span class="token comment">// 抛出 IllegalArgumentException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>建议在构建 Agent 时，<strong>总是 try-catch 包一下</strong>，或者在工厂方法中加入前置校验：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">HarnessAgent</span> <span class="token function">createSafely</span><span class="token punctuation">(</span><span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">Model</span> model<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">Objects</span><span class="token punctuation">.</span><span class="token function">requireNonNull</span><span class="token punctuation">(</span>name<span class="token punctuation">,</span> <span class="token string">&quot;Agent name must not be null&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">Objects</span><span class="token punctuation">.</span><span class="token function">requireNonNull</span><span class="token punctuation">(</span>model<span class="token punctuation">,</span> <span class="token string">&quot;Model must not be null&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>name<span class="token punctuation">.</span><span class="token function">isBlank</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">IllegalArgumentException</span><span class="token punctuation">(</span><span class="token string">&quot;Agent name must not be blank&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token class-name">HarnessAgent</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">name</span><span class="token punctuation">(</span>name<span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">model</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="七、小结" tabindex="-1"><a class="header-anchor" href="#七、小结" aria-hidden="true">#</a> 七、小结</h2><p>到这里，关于 AgentScope Java 2.0 的 Builder 模式、流式输出和思考模式，我们已经有了完整的认识。回顾一下今天的核心内容：</p><h3 id="_1-builder-模式的设计哲学" tabindex="-1"><a class="header-anchor" href="#_1-builder-模式的设计哲学" aria-hidden="true">#</a> 1. Builder 模式的设计哲学</h3><ul><li>Agent 有大量可选配置项，Builder 模式让代码<strong>可读、安全、灵活</strong></li><li>Builder 链把&quot;我要什么&quot;说清楚，不关心&quot;怎么拼起来&quot;</li><li>纯 Java 实现，不绑定 Spring，在任何环境下都能使用</li></ul><h3 id="_2-流式输出全解析" tabindex="-1"><a class="header-anchor" href="#_2-流式输出全解析" aria-hidden="true">#</a> 2. 流式输出全解析</h3><ul><li><code>streamEvents()</code> 覆盖 Agent 执行的完整生命周期</li><li>6 类核心事件：AgentStart / ThinkingBlock / TextBlock / ToolCall / ToolResult / AgentEnd</li><li>通过事件类型分发，可以实现类似 ChatGPT 的流式打字效果</li></ul><h3 id="_3-思考模式-thinking-mode" tabindex="-1"><a class="header-anchor" href="#_3-思考模式-thinking-mode" aria-hidden="true">#</a> 3. 思考模式（Thinking Mode）</h3><ul><li><strong>ThinkingBlock 事件</strong>= 模型原生思维链（需推理模型支持）</li><li><strong>Prompt 模拟思考</strong>= 通过 <code>&lt;thinking&gt;</code> 标签让普通模型展示推理过程</li><li>思考 + 行动 + 再思考 = ReAct 循环与思维链的完美协同</li></ul><h3 id="_4-最佳实践" tabindex="-1"><a class="header-anchor" href="#_4-最佳实践" aria-hidden="true">#</a> 4. 最佳实践</h3><ul><li>用工厂方法封装 Builder 创建逻辑</li><li>Model 对象线程安全，可以复用</li><li>在 <code>build()</code> 之前做好参数校验</li></ul><p><strong>最后放一张对比表，帮大家快速选择：</strong></p><table><thead><tr><th>场景</th><th>推荐 Agent</th><th>Builder 关键配置</th></tr></thead><tbody><tr><td>纯对话聊天</td><td>ReActAgent</td><td><code>.model(xxx).stream(true).maxIters(3)</code></td></tr><tr><td>带工具的助手</td><td>ReActAgent / HarnessAgent</td><td><code>.model().toolkit().maxIters(10)</code></td></tr><tr><td>需要记忆持久化</td><td>HarnessAgent</td><td><code>.workspace().model()</code></td></tr><tr><td>深度推理 + 搜索</td><td>HarnessAgent</td><td><code>.model(推理模型).toolkit().enablePlanMode()</code></td></tr><tr><td>Web 后端对接</td><td>HarnessAgent</td><td><code>.workspace().middleware().streamEvents()</code></td></tr></tbody></table><h2 id="八、其他" tabindex="-1"><a class="header-anchor" href="#八、其他" aria-hidden="true">#</a> 八、其他</h2><h3 id="_0-项目" tabindex="-1"><a class="header-anchor" href="#_0-项目" aria-hidden="true">#</a> 0. 项目</h3>`,114),r={href:"https://github.com/liuyueyi/spring-ai-demo/agent-scope",target:"_blank",rel:"noopener noreferrer"},m={href:"https://java.agentscope.io/v2/zh/docs/harness/workspace.html",target:"_blank",rel:"noopener noreferrer"},v={href:"https://java.agentscope.io/v2/zh/docs/building-blocks/message-and-event.html",target:"_blank",rel:"noopener noreferrer"},b={href:"https://java.agentscope.io/v2/zh/docs/building-blocks/agent.html",target:"_blank",rel:"noopener noreferrer"},g=n("h3",{id:"_1-下篇预告",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#_1-下篇预告","aria-hidden":"true"},"#"),s(" 1. 下篇预告")],-1),h=n("p",null,"本文是【AgentScope Java 新手村系列】的第三篇。回顾一下系列进度：",-1),f={href:"https://mp.weixin.qq.com/s/u4wERL0UXChPgvWQJpwurA",target:"_blank",rel:"noopener noreferrer"},q=p('<li>✅ <strong><a href="">第2篇：ReActAgent 核心拆解</a></strong>：理解&quot;思考→行动→观察&quot;的推理循环</li><li>✅ <strong>第3篇：你的第一个 Java Agent</strong>：Builder 模式全面解析 + 流式输出 + 思考模式</li><li>🔜 <strong>第4篇：工具系统（Tools）实战</strong> —— 用 <code>@Tool</code> 注解将任意 Java 方法注册为 Agent 工具，实现文件读写、HTTP 调用、数据库查询等骚操作</li><li>🔜 <strong>第5篇：结构化输出</strong> —— 让 Agent 直接返回指定的 Java 类型数据</li>',4),y=p("<p>今天讲完了 Builder 模式和流式输出的全貌，不知道各位小伙伴有没有注意到一个细节——<strong>ThinkingBlock 事件其实是&quot;模型内部的思考&quot;，而 <code>@Tool</code> 注解的注册是&quot;Agent 在框架层面的行动&quot;</strong>。这两者一个对内、一个对外，构成了 Agent 完整的心智模型。</p><p>那么问题来了——工具到底怎么定义？<code>@Tool</code> 注解的参数有哪些讲究？工具调用失败后 Agent 会自动重试吗？这些内容，我们下一篇再详细介绍。</p><p>尽信书则不如，以上内容，纯属一家之言，因个人能力有限，难免有疏漏和错误之处，如发现 bug 或者有更好的建议，欢迎批评指正，不吝感激。</p><blockquote><p><strong>微信公众号: 一灰灰Blog</strong> —— 关注获取最新技术文章推送</p></blockquote>",4);function A(w,T){const a=i("ExternalLinkIcon");return o(),c("div",null,[k,l(" more "),d,n("ul",null,[n("li",null,[s("项目地址："),n("a",r,[s("https://github.com/liuyueyi/spring-ai-demo/agent-scope"),t(a)])]),n("li",null,[s("Builder 模式官方示例："),n("a",m,[s("https://java.agentscope.io/v2/zh/docs/harness/workspace.html"),t(a)])]),n("li",null,[s("消息与事件系统："),n("a",v,[s("https://java.agentscope.io/v2/zh/docs/building-blocks/message-and-event.html"),t(a)])]),n("li",null,[s("Agent 创建与配置："),n("a",b,[s("https://java.agentscope.io/v2/zh/docs/building-blocks/agent.html"),t(a)])])]),g,h,n("ul",null,[n("li",null,[s("✅ "),n("strong",null,[n("a",f,[s("第1篇：简介与环境搭建"),t(a)])]),s("：从零搭环境，跑通第一个 Agent 对话")]),q]),y])}const S=e(u,[["render",A],["__file","03.AgentScope Java 2.0 你的第一个 Java Agent.html.vue"]]);export{S as default};
